/bin/bash -lc "cd [workspace path] && python3 -c \"
import numpy as np
d = np.load('source_pixels.npz')['rgb']
def ballmask(f):
    R,G,B = f[...,0].astype(int), f[...,1].astype(int), f[...,2].astype(int)
    return (R>140)&(G>55)&(G<140)&(B<100)&(R>G+40)
rows=[]
for i in range(96):
    m=ballmask(d[i]); ys,xs=np.where(m)
    rows.append((i,xs.min(),xs.max(),ys.min(),ys.max(),xs.mean(),ys.mean(),len(xs)))
for r in rows[::3]:
    print('%2d x[%3d,%3d] y[%3d,%3d] cx=%6.2f cy=%6.2f n=%4d'%r)
\" > .tmp/ball_track.txt; cat .tmp/ball_track.txt"
